/**
 * Heliacal golden: the TS port of the visibility model must agree with the
 * Python reference at each instant, find the same event in each search (or
 * none where the reference finds none), and score each crescent the same.
 * Both run the SAME cases (from heliacal-golden.json, generated by
 * python/export_heliacal_golden.py) on the same data.
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { Engine } from "../src/chart.js";
import { calendarDate, julianDay } from "../src/core.js";
import { loadNodeData } from "../src/node-loader.js";
import {
  heliacal, heliacalKindsFor, localDay, lunarCrescent, visibility, HELIACAL_KINDS,
  type HeliacalOptions,
} from "../src/heliacal.js";

const here = dirname(fileURLToPath(import.meta.url));
const G = JSON.parse(readFileSync(join(here, "../../test/heliacal-golden.json"), "utf8"));
const eng = new Engine(loadNodeData(join(here, "../../data"), "embedded", "full"));

let checks = 0;
let failures = 0;
let worstJd = 0;
const TOL_JD = 1e-6;  // days (~0.09 s)
const TOL = 1e-6;     // magnitudes, degrees, q

const ok = (cond: boolean, msg: string): void => {
  checks++;
  if (!cond) { failures++; console.error(`FAIL ${msg}`); }
};

const SNAKE: Record<string, string> = {
  sunAltitude: "sun_altitude", moonAltitude: "moon_altitude",
  skyBrightness: "sky_brightness", limitingMagnitude: "limiting_magnitude",
  arcusVisionis: "arcus_visionis", sunDepression: "sun_depression",
  lagMinutes: "lag_minutes",
};
const JD_KEYS = new Set(["jd", "conjunction", "earliest", "latest", "sun", "moon"]);

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function same(id: string, got: any, want: any): void {
  const keys = new Set(Object.keys(got).map((k) => SNAKE[k] ?? k));
  ok(Object.keys(want).every((k) => keys.has(k)) && keys.size === Object.keys(want).length,
    `${id}: fields ${[...keys].sort()} vs ${Object.keys(want).sort()}`);
  for (const [k, g] of Object.entries(got)) {
    const w = want[SNAKE[k] ?? k];
    if (typeof g === "number" && typeof w === "number") {
      const diff = Math.abs(g - w);
      if (JD_KEYS.has(k)) {
        if (diff > worstJd) worstJd = diff;
        ok(diff <= TOL_JD, `${id}.${k}: ${g} vs ${w} (${diff} d)`);
      } else {
        // sky brightness spans nine decades; compare it relatively
        ok(diff <= TOL * Math.max(1, Math.abs(w)), `${id}.${k}: ${g} vs ${w}`);
      }
    } else {
      ok(g === w, `${id}.${k}: ${g} vs ${w}`);
    }
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
for (const c of G.instants as any[]) {
  const o = c.options ?? {};
  const got = visibility(eng, c.target, c.jd, c.lat, c.lon, { extinction: o.extinction, altM: o.alt_m });
  same(c.id, got, c.result);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
for (const c of G.events as any[]) {
  const o = c.options ?? {};
  const opts: HeliacalOptions = {
    kind: o.kind, method: o.method, extinction: o.extinction, spread: o.spread,
    arcusVisionis: o.arcus_visionis, altM: o.alt_m, span: o.span,
  };
  const got = heliacal(eng, c.target, c.jd, c.lat, c.lon, opts);
  ok((got === null) === (c.result === null), `${c.id}: found in one engine and not the other`);
  if (got && c.result) same(c.id, got, c.result);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
for (const c of G.crescents as any[]) {
  const got = lunarCrescent(eng, c.day, c.lat, c.lon, { half: c.half });
  ok((got === null) === (c.result === null), `${c.id}: scored in one engine and not the other`);
  if (got && c.result) same(c.id, got, c.result);
}

// The shape of the answer, stated as facts a reader would rely on.
{
  const start = julianDay(139, 1, 1, 0, 0, 0, "julian");
  const ev = heliacal(eng, "Sirius", start, 29.85, 31.25)!;
  const d = calendarDate(ev.jd, "julian");
  ok(d.year === 139 && d.month === 7 && d.day === 19, `Sirius rises heliacally at Memphis on 19 July 139 (${JSON.stringify(d)})`);
  ok(ev.earliest! <= ev.jd && ev.jd <= ev.latest! && ev.latest! - ev.earliest! < 4,
    "its window under a clearer and a hazier sky is a few days wide");
  ok(ev.extinction === 0.25 && ev.spread === 0.05, "the result echoes its atmosphere");
  const back = heliacal(eng, "Sirius", start, 29.85, 31.25, {
    method: "arcus", arcusVisionis: ev.arcusVisionis! - 1e-6,
  })!;
  ok(localDay(back.jd, 31.25) === localDay(ev.jd, 31.25), "the implied arcus visionis gives the same day back");
  ok(HELIACAL_KINDS.length === 6, "six kinds of event");
  ok(heliacalKindsFor(eng, "Sirius").join() === "morning_first,evening_last", "a star has a rising and a setting");
  ok(heliacalKindsFor(eng, "venus").length === 4 && heliacalKindsFor(eng, "moon").join() === "evening_first,morning_last",
    "Venus has four events and the Moon two");
  ok(heliacalKindsFor(eng, "mars", "arcus").includes("acronychal_rising") && heliacalKindsFor(eng, "moon", "arcus").length === 0,
    "the arcus method adds the opposition events and has none for the Moon");
  ok(heliacal(eng, "Sirius", start, 29.85, 31.25, { span: 120 }) === null
    && heliacal(eng, "Sirius", start, 29.85, 31.25, { span: 220 })!.jd === ev.jd,
    "span cuts the search short and does not move an event inside it");
  const moon = heliacal(eng, "moon", julianDay(2025, 3, 1), 21.42, 39.83, { kind: "evening_first" })!;
  ok(moon.method === "crescent" && (moon.zone === "A" || moon.zone === "B") && moon.q! > -0.014,
    "the new crescent is found by Yallop's test");
  const throws = (fn: () => unknown): boolean => {
    try { fn(); } catch (e) { return e instanceof Error; }
    return false;
  };
  ok(throws(() => heliacal(eng, "moon", start, 30, 31)), "the Moon has no morning first");
  ok(throws(() => heliacal(eng, "jupiter", start, 30, 31, { kind: "evening_first" })), "Jupiter has no evening first");
  ok(throws(() => heliacal(eng, "Sirius", start, 30, 31, { method: "arcus" })), "the arcus method needs its angle");
  ok(throws(() => heliacal(eng, "Sirius", start, 30, 31, { kind: "acronychal_rising" })),
    "the opposition events need the arcus method");
  ok(throws(() => heliacal(eng, "Nibiru", start, 30, 31)), "an unknown target is refused");
  ok(throws(() => heliacalKindsFor(eng, "Nibiru")), "and has no kinds");
  ok(throws(() => heliacal(eng, "Sirius", start, 30, 31, { span: 0 })), "a span must be positive");
  ok(throws(() => visibility(eng, "moon", start, 30, 31)), "visibility refuses the Moon");
}

console.log(`${checks} checks, ${failures} failures (worst instant ${(worstJd * 86400).toFixed(4)} s)`);
process.exit(failures === 0 ? 0 : 1);
